<?php
namespace Database\Factories;use App\Models\Industry;use Illuminate\Database\Eloquent\Factories\Factory;use Illuminate\Support\Str;class IndustryFactory extends Factory{protected $model=Industry::class;public function definition():array{$title=fake()->unique()->words(3,true);return ['title'=>Str::title($title),'slug'=>Str::slug($title).'-'.fake()->unique()->numberBetween(1000,9999),'short_description'=>fake()->sentence(),'hero_style'=>'standard','template'=>'standard','status'=>'draft','display_order'=>1,'robots_index'=>true,'robots_follow'=>true];}public function published():static{return $this->state(fn()=>['status'=>'published','published_at'=>now(),'archived_at'=>null]);}public function scheduled(?\DateTimeInterface $when=null):static{return $this->state(fn()=>['status'=>'scheduled','scheduled_for'=>$when?:now()->addDay(),'archived_at'=>null]);}public function archived():static{return $this->state(fn()=>['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);}}
